// shapes: icons in the -50..50 box, keeping each shape's aspect
SHAPES.forEach((sh) => {
  const w = sh.aspect >= 1 ? 84 : 84 * sh.aspect, h = sh.aspect >= 1 ? 84 / sh.aspect : 84;
  ART[`shape-${sh.id}`] = () => <path d={sh.path} transform={`translate(${-w / 2} ${-h / 2}) scale(${w / 100} ${h / 100})`} fill={sh.colour} stroke={K} strokeWidth={2.2} vectorEffect="non-scaling-stroke" strokeLinejoin="round" />;
});
ART.sparrow = ART.bird;
// colours: paint splashes
(Object.keys(COLOUR_NAMES) as ColourId[]).forEach((c) => { ART[`c-${c}`] = () => blob(COLOUR_NAMES[c].hex); });

/** Picture / prop: original SVG when available, otherwise the item's emoji. `label` makes it an accessible image. */
export function Art({ id, v, label, shadow, className = '' }: { id: string; v?: string; label?: string; shadow?: boolean; className?: string }) {
  const a11y = label ? { role: 'img' as const, 'aria-label': label } : { 'aria-hidden': true as const };
  if (id.startsWith('num:')) {
    const n = Number(id.slice(4));
    return (
      <svg viewBox="-50 -50 100 100" className={`el-art ${className}`} {...a11y}>
        <text y={-6} textAnchor="middle" fontSize={44} fontWeight={800} fill="currentColor" fontFamily="var(--font-kid)">{n}</text>
        {Array.from({ length: n }, (_, i) => <circle key={i} cx={(i - (n - 1) / 2) * 16} cy={30} r={6} fill="#E0A63A" stroke={K} strokeWidth={1.5} />)}
      </svg>
    );
  }
  const draw = ART[id];
  return (
    <svg viewBox="-50 -50 100 100" className={`el-art ${shadow ? 'el-shadow' : ''} ${className}`} {...a11y}>
      {draw ? draw(v) : <text textAnchor="middle" dominantBaseline="central" fontSize={70}>{PIC[id]?.emoji ?? '❓'}</text>}
    </svg>
  );
}
export const hasDrawing = (id: string) => !!ART[id];

/** Story backgrounds on a 400×260 stage. */
export function Backdrop({ bg }: { bg: Bg }) {
  const sky = { day: '#CFE6F2', hot: '#F6E3B0', garden: '#D6ECF2', rain: '#AEB9C2', village: '#D9ECF3', festival: '#5A3D52', night: '#26304F', road: '#D3E7F0', river: '#D3E7F0', room: '#F1E4CF', bathroom: '#DCEBEF', forest: '#CFE6D8', riverbank: '#D3E7F0', sea: '#CFE6F2', bedroom: '#3E4466', evening: '#F2CFA4' }[bg];
  const ground = { day: '#A9CF95', hot: '#D8C27A', garden: '#9CC98A', rain: '#86A579', village: '#B9D79E', festival: '#8A5A46', night: '#344536', road: '#9CC98A', river: '#9CC98A', room: '#C9A87E', bathroom: '#BFD6DC', forest: '#86B57A', riverbank: '#9CC98A', sea: '#E9D3A0', bedroom: '#5A4A5E', evening: '#94B07A' }[bg];
  const groundY = { river: 150, riverbank: 140, sea: 215 }[bg as string] ?? 190;
  return (
    <g aria-hidden="true">
      <rect width={400} height={260} fill={sky} />
      {(bg === 'room' || bg === 'bathroom' || bg === 'festival' || bg === 'bedroom') ? (
        <>
          <rect y={200} width={400} height={60} fill={ground} />
          {bg === 'room' && <g><rect x={50} y={30} width={90} height={80} fill="#CFE6F2" stroke={K} strokeWidth={3} /><path d="M95 30 V110 M50 70 H140" stroke={K} strokeWidth={2} /></g>}
          {bg === 'bedroom' && <g><rect x={260} y={30} width={90} height={80} fill="#1E2744" stroke={K} strokeWidth={3} /><path d="M318 46 a12 12 0 1 0 10 18 a9 9 0 1 1 -10 -18Z" fill="#F4E3A1" /><circle cx={280} cy={50} r={1.6} fill="#F4EBC2" /><circle cx={300} cy={90} r={1.4} fill="#F4EBC2" /><circle cx={338} cy={96} r={1.4} fill="#F4EBC2" /><path d="M305 30 V110 M260 70 H350" stroke={K} strokeWidth={2} /></g>}
          {bg === 'bathroom' && <g>{Array.from({ length: 8 }, (_, i) => <path key={i} d={`M${i * 50} 0 V200`} stroke="#C3D9DF" strokeWidth={2} />)}<rect x={300} y={40} width={70} height={60} rx={8} fill="#E6F2FA" stroke={K} strokeWidth={2} /></g>}
          {bg === 'festival' && <g>{Array.from({ length: 9 }, (_, i) => <path key={i} d={`M${i * 50} 10 q25 22 50 0`} stroke="#F2B33D" strokeWidth={3} fill="none" />)}{Array.from({ length: 9 }, (_, i) => <circle key={`b${i}`} cx={i * 50 + 25} cy={21} r={4} fill={['#E8862E', '#D0577A', '#F2C14E'][i % 3]} />)}<g transform="translate(200 236)"><ellipse rx={60} ry={14} fill="none" stroke="#F2E2C6" strokeWidth={3} /><ellipse rx={36} ry={8} fill="none" stroke="#E58FB0" strokeWidth={3} /></g></g>}
        </>
      ) : (
        <>
          {bg === 'night' && Array.from({ length: 14 }, (_, i) => <circle key={i} cx={(i * 73) % 400} cy={(i * 37) % 120 + 10} r={1.4} fill="#F4EBC2" />)}
          {(bg === 'village' || bg === 'garden') && <path d="M0 170 Q80 120 160 160 T320 150 T400 160 V260 H0Z" fill="#8FBF7F" />}
          {bg === 'evening' && <path d="M0 170 Q80 120 160 160 T320 150 T400 160 V260 H0Z" fill="#A9B97E" />}
          {bg === 'forest' && [30, 110, 190, 270, 350].map((x, i) => <g key={x}><rect x={x - 4} y={140} width={8} height={55} fill="#7A5A3E" /><circle cx={x} cy={128} r={30 + (i % 2) * 8} fill="#79A873" /><circle cx={x + 18} cy={142} r={20} fill="#6E9F6A" /></g>)}
          {bg === 'sea' && <g><rect y={125} width={400} height={95} fill="#5DA9DA" /><path d="M0 150 q20 -6 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 M0 185 q25 -7 50 0 t50 0 t50 0 t50 0 t50 0 t50 0 t50 0 t50 0" stroke="#FFFFFF" strokeWidth={2} fill="none" opacity={0.55} /></g>}
          <rect y={groundY} width={400} height={260 - groundY} fill={ground} />
          {bg === 'sea' && <path d="M0 215 q25 -8 50 0 t50 0 t50 0 t50 0 t50 0 t50 0 t50 0 t50 0" stroke="#FFFFFF" strokeWidth={3} fill="none" opacity={0.8} />}
          {bg === 'riverbank' && <g><rect y={172} width={400} height={56} fill="#7DB7D9" /><path d="M0 192 q20 -6 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 M20 212 q20 -5 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0" stroke="#FFFFFF" strokeWidth={2} fill="none" opacity={0.6} /><path d="M24 240 q-4 -14 -10 -20 M30 240 q0 -16 4 -24 M366 242 q-2 -14 -8 -20 M372 242 q2 -16 8 -22" stroke="#4E8F52" strokeWidth={2.4} fill="none" strokeLinecap="round" /></g>}
          {bg === 'road' && <g><rect y={215} width={400} height={30} fill="#7D7D7D" /><path d="M0 230 H400" stroke="#F2F2F2" strokeWidth={3} strokeDasharray="20 16" /></g>}
          {bg === 'river' && <g><rect y={180} width={400} height={80} fill="#7DB7D9" /><path d="M0 200 q20 -6 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0" stroke="#fff" strokeWidth={2} fill="none" opacity={0.6} /><path d="M40 140 H360 V150 H40Z M80 150 V180 M200 150 V180 M320 150 V180" fill="#9B8B7A" stroke="#6B5B4B" strokeWidth={4} /></g>}
          {bg === 'village' && <path d="M20 190 L50 160 L80 190Z" fill="#C98B5B" stroke={K} strokeWidth={1.5} />}
          {bg === 'rain' && Array.from({ length: 22 }, (_, i) => <path key={i} d={`M${(i * 53) % 400} ${(i * 29) % 170} l-4 12`} stroke="#5E8FB5" strokeWidth={2} strokeLinecap="round" />)}
          {bg === 'hot' && <path d="M0 200 q50 -6 100 0 t100 0 t100 0 t100 0" stroke="#C9A65A" strokeWidth={2} fill="none" />}
        </>
      )}
    </g>
  );
}

/** Eyes of story characters (art box coords + lid colour) for a gentle blink. */
const EYES = (c: string, ...e: [number, number, number][]) => ({ c, e });
const PERSON_EYES = EYES(SKIN, [-6, -19, 2.4], [6, -19, 2.4]);
export const BLINK: Record<string, { c: string; e: [number, number, number][] }> = {
  cat: EYES('#E39B4F', [-7, -18, 3], [7, -18, 3]), dog: EYES('#C99460', [-24, -16, 2.6], [-12, -16, 2.6]), cow: EYES('#F7F4EC', [30, -14, 2.4], [40, -14, 2.4]),
  frog: EYES('#5BAA4F', [-16, -13, 6.5], [16, -13, 6.5]), hen: EYES('#F7F4EC', [-22, -16, 2.6]), chick: EYES('#F5D547', [-12, -17, 2.8]), crow: EYES('#2F2F33', [-22, -15, 3.4]),
  bird: EYES('#9B6B43', [-16, -8, 2.4]), peacock: EYES('#2F6FB5', [-5, -25, 2]), sun: EYES('#F2C14E', [-8, -4, 2.8], [8, -4, 2.8]),
  child: PERSON_EYES, mother: PERSON_EYES, adult: PERSON_EYES, father: PERSON_EYES, grandmother: PERSON_EYES, grandfather: PERSON_EYES, baby: EYES(SKIN, [-8, -14, 2.8], [8, -14, 2.8]),
  farmer: PERSON_EYES, hunter: PERSON_EYES,
  lion: EYES('#F2C76A', [-21, -13, 2.6], [-11, -13, 2.6]), rabbit: EYES('#EDE9E1', [-19, -9, 2.8]), elephant: EYES('#9AA3AD', [-28, -14, 2.6]),
  monkey: EYES('#E8C9A3', [-5, -20, 2.6], [5, -20, 2.6]), crocodile: EYES('#6A9A55', [-26, -14, 3.4]), pigeon: EYES('#C9D0D8', [-18, -10, 2.8]),
  owl: EYES('#9B6B43', [-11, -10, 9.6], [11, -10, 9.6]), rooster: EYES('#E8A03A', [-20, -16, 2.6]), goat: EYES('#F1EEE8', [32, -12, 2.4]), duck: EYES('#F7F4EC', [-16, -10, 2.6]),
};
/** Eyelids that close briefly a few times (CSS, stops after ~20 s; none in reduced motion). */
export function Lids({ art, i = 0 }: { art: string; i?: number }) {
  const b = BLINK[art];
  if (!b) return null;
  return <g aria-hidden="true">{b.e.map(([x, y, r], j) => <ellipse key={j} className="el-lid" style={{ animationDelay: `${1.2 + ((i * 0.9) % 3)}s` }} cx={x} cy={y} rx={r + 0.6} ry={r + 0.6} fill={b.c} />)}</g>;
}
